# app/main.py — Starter code for Render deployment
from fastapi import FastAPI
import os

app = FastAPI(
    title="TechPath API",
    description="Student management API — TechPath Institute, Bhopal",
    version="1.0.0"
)

@app.get("/health")
async def health_check():
    """Health check endpoint — Render pings this to verify the app is alive."""
    return {
        "status": "healthy",
        "app": "TechPath API",
        "environment": os.getenv("APP_ENV", "development")
    }

@app.get("/")
async def root():
    return {
        "message": "Welcome to TechPath API!",
        "docs": "/docs",
        "health": "/health"
    }

